import{_ as s,o as p,a as n,b as l}from"./app.BGziXukh.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/SetFixPipeReluAlpha.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/SetFixPipeReluAlpha.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1794273950000}'),e={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/SetFixPipeReluAlpha.md"};function t(i,a,c,d,r,o){return p(),n("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>SetFixPipeReluAlpha<span id="ZH-CN_TOPIC_0000002738231208"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section18204144912492"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>KirinX90处理器系列产品：不支持</li></ul></div><div data-filter="9020"><ul><li>Kirin9020处理器系列产品：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin9030处理器系列产品：不支持</li></ul></div><div data-filter="9050"><ul><li>Kirin9050处理器系列产品：支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_macro_intf.h&quot;</code>。</p><p>MacroCube计算（如<a href="../mmad_compute/MmadFix.html">MmadFix</a>、ConvFix）过程中，开启激活（ReLU）后处理功能时，通过调用该接口设置激活函数的LUT（Look-Up Table）模式和preValue参数。</p><p>lut_mode_t枚举类型定义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">enum</span><span class="w"> </span><span class="k">class</span><span class="w"> </span><span class="nc">lut_mode_t</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="p">{</span><span class="w"> </span><span class="n">Gelu</span><span class="p">,</span><span class="w"> </span><span class="n">Silu</span><span class="p">,</span><span class="w"> </span><span class="n">Sigmoid</span><span class="p">,</span><span class="w"> </span><span class="n">Tanh</span><span class="w"> </span><span class="p">};</span>
</code></pre></div><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetFixPipeReluAlpha</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">FixPipeReluAlphaBitModeParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">params</span><span class="p">)</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetFixPipeReluAlpha</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">FixPipeReluAlphaParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">params</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>params</td><td>输入</td><td>激活相关参数，类型为FixPipeReluAlphaParams或FixPipeReluAlphaBitModeParams。<br>FixPipeReluAlphaParams的具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_macro.h</code>，FixPipeReluAlphaBitModeParams的具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_operator_macro_bitmode_intf.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。<br>FixPipeReluAlphaParams参数说明请参考<a href="#table2fixpipereulalpha">表2</a>，FixPipeReluAlphaBitModeParams参数说明请参考<a href="#table3fixpipereulalpha">表3</a>。</td></tr></tbody></table><p><span id="table2fixpipereulalpha"></span><strong>表2</strong> FixPipeReluAlphaParams结构体内参数说明</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>lut</td><td>激活函数的LUT模式，lut_mode_t枚举类型，默认值为Gelu。取值包括：Gelu、Silu、Sigmoid、Tanh。</td></tr><tr><td>preValue</td><td>激活函数计算时使用的scalar参数，uint32_t类型，默认值为0。传入时需将float类型的参数转换为uint32_t类型。</td></tr></tbody></table><p><span id="table3fixpipereulalpha"></span><strong>表3</strong> FixPipeReluAlphaBitModeParams类参数说明</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>config0</td><td>uint64_t类型，与FixPipeReluAlphaBitModeConfig0位域（bit-field）结构体类型参数config0BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig0()函数获取其值。</td></tr><tr><td>config0BitMode</td><td>FixPipeReluAlphaBitModeConfig0位域（bit-field）结构体类型，参数参考<a href="#table4fixpipereulalpha">表4</a>，与config0组成联合体（union）。</td></tr></tbody></table><p>FixPipeReluAlphaBitModeParams对于FixPipeReluAlphaParams结构体构造进行了优化，本接口适用于scalar流水成为性能优化瓶颈的场景。FixPipeReluAlphaBitModeParams类使用union与bit-field方法，采用bit位表达参数类型，使用bit-field结构体自动处理入参的bit位数，并利用union的特性实现多参数融合传递，仅需传递一个入参即可包含全部所需信息，对应底层接口仅需要接收一个参数。同时，当需要修改参数中某一bit位的值时，仅需要通过循环和位运算即可实现，不需要重新传入参数，减少了scalar计算，实现性能提升。</p><p>FixPipeReluAlphaBitModeParams类可以直接使用FixPipeReluAlphaParams结构体类型对象初始化：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">FixPipeReluAlphaBitModeParams</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">FixPipeReluAlphaParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">fixPipeReluAlphaParams</span><span class="p">);</span>
</code></pre></div><p>也可以使用各参数的Set函数修改参数值，并且由于使用了联合体，还可以对config0直接进行逐bit位修改来修改参数。</p><p><span id="table4fixpipereulalpha"></span><strong>表4</strong> FixPipeReluAlphaBitModeConfig0结构体参数说明</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>lut</td><td>激活函数的LUT模式，lut_mode_t枚举类型。<br>该参数是位域结构体的最低位参数，占用3bit，可以使用FixPipeReluAlphaBitModeParams类对象的SetLut()函数设置其值，使用GetLut()函数获取其值。</td></tr><tr><td>reserved0</td><td>预留参数，占用10bit。</td></tr><tr><td>preValue</td><td>激活函数计算时使用的scalar参数。<br>该参数是位域结构体的最高位参数，占用19bit，可以使用FixPipeReluAlphaBitModeParams类对象的SetPreValue()函数设置其值，使用GetPreValue()函数获取其值。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>支持的数据类型为：uint32_t、uint64_t。</p><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>该接口需配合MacroCube系列计算接口（如<a href="../mmad_compute/MmadFix.html">MmadFix</a>、ConvFix）一起使用，需在MacroCube计算接口之前调用。</li><li>本章节涉及寄存器在相同核函数（Kernel）内部会维持状态直到被人为改变，而在不同核函数（Kernel）内部不会继承之前的状态。</li></ul><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 设置激活函数LUT模式和preValue参数</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">lut_mode_t</span><span class="w"> </span><span class="n">lutMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">lut_mode_t</span><span class="o">::</span><span class="n">Gelu</span><span class="p">;</span>
<span class="kt">float</span><span class="w"> </span><span class="n">tmp</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="kt">float</span><span class="p">)</span><span class="mf">0.5</span><span class="p">;</span>
<span class="c1">// 将float类型的tmp转换为uint32_t的preValue</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">preValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="o">*</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">tmp</span><span class="p">));</span>

<span class="c1">// 方式一：使用FixPipeReluAlphaParams结构体</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">FixPipeReluAlphaParams</span><span class="w"> </span><span class="nf">reluAlphaParams</span><span class="p">(</span><span class="n">lutMode</span><span class="p">,</span><span class="w"> </span><span class="n">preValue</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixPipeReluAlpha</span><span class="p">(</span><span class="n">reluAlphaParams</span><span class="p">);</span>

<span class="c1">// 方式二：使用FixPipeReluAlphaBitModeParams类（适用于scalar流水成为性能优化瓶颈的场景）</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">FixPipeReluAlphaBitModeParams</span><span class="w"> </span><span class="nf">reluAlphaBitModeParams</span><span class="p">(</span><span class="n">reluAlphaParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixPipeReluAlpha</span><span class="p">(</span><span class="n">reluAlphaBitModeParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const m=s(e,[["render",t]]);export{u as __pageData,m as default};
